describe('CameraTransition', () => {
  const from = createCameraPose({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 1 }, 50);
  const to = createCameraPose({ x: 10, y: 0, z: 0 }, { x: 10, y: 0, z: 1 }, 70);

  it('is idle until it is started', () => {
    const transition = new CameraTransition();
    expect(transition.isActive).toBe(false);
    expect(transition.update(FRAME, to)).toEqual(to);
  });

  it('blends from the captured pose to the destination', () => {
    const transition = new CameraTransition();
    transition.start(from, { durationSeconds: 1, easing: 'linear' });
    const half = transition.update(0.5, to);
    expect(half.position.x).toBeCloseTo(5, 6);
    expect(half.fov).toBeCloseTo(60, 6);
    expect(transition.progress).toBeCloseTo(0.5, 6);
    expect(transition.isActive).toBe(true);
  });

  it('finishes exactly on the destination and deactivates', () => {
    const transition = new CameraTransition();
    transition.start(from, { durationSeconds: 0.5, easing: 'linear' });
    transition.update(0.25, to);
    expect(transition.update(0.3, to)).toEqual(to);
    expect(transition.isActive).toBe(false);
  });

  it('treats a non-positive duration as an instant cut', () => {
    const transition = new CameraTransition();
    transition.start(from, { durationSeconds: 0 });
    expect(transition.isActive).toBe(false);
    expect(transition.update(FRAME, to)).toEqual(to);
  });

  it('follows a destination that keeps moving', () => {
    const transition = new CameraTransition();
    transition.start(from, { durationSeconds: 1, easing: 'linear' });
    const moving = createCameraPose({ x: 20, y: 0, z: 0 }, { x: 20, y: 0, z: 1 }, 50);
    expect(transition.update(0.5, moving).position.x).toBeCloseTo(10, 6);
  });

  it('restarts from the live pose without jumping', () => {
    const transition = new CameraTransition();
    transition.start(from, { durationSeconds: 1, easing: 'linear' });
    const mid = transition.update(0.5, to);
    transition.start(mid, { durationSeconds: 1, easing: 'linear' });
    expect(cameraPoseDistance(transition.update(0, to), mid)).toBeCloseTo(0, 6);
  });
});

describe('SmoothCameraRig', () => {
  const start = createCameraPose({ x: 0, y: 2, z: 6 }, { x: 0, y: 0, z: 0 }, 55);
  const desired = createCameraPose({ x: 8, y: 3, z: 0 }, { x: 8, y: 0, z: 0 }, 60);

  it('snaps without smoothing', () => {
    const rig = new SmoothCameraRig(start);
    expect(rig.snapTo(desired)).toEqual(desired);
    expect(rig.current).toEqual(desired);
  });

  it('eases toward the desired pose and settles on it', () => {
    const rig = new SmoothCameraRig(start);
    const firstFrame = rig.update(FRAME, desired);
    expect(cameraPoseDistance(firstFrame, start)).toBeGreaterThan(0);
    expect(cameraPoseDistance(firstFrame, desired)).toBeGreaterThan(1);

    for (let i = 0; i < 400; i += 1) rig.update(FRAME, desired);
    expect(cameraPoseDistance(rig.current, desired)).toBeLessThan(0.01);
    expect(rig.current.fov).toBeCloseTo(60, 3);
  });

  it('clamps huge frame deltas so the camera never teleports', () => {
    const rig = new SmoothCameraRig(start, { maxDeltaSeconds: 0.1, positionSmoothTime: 0.5 });
    expect(cameraPoseDistance(rig.update(30, desired), desired)).toBeGreaterThan(4);
  });

  it('ignores invalid deltas', () => {
    const rig = new SmoothCameraRig(start);
    expect(rig.update(0, desired)).toEqual(start);
    expect(rig.update(Number.NaN, desired)).toEqual(start);
  });

  it('runs a transition and hands control back to the springs', () => {
    const rig = new SmoothCameraRig(start);
    rig.transitionTo({ durationSeconds: 0.5, easing: 'linear' });
    expect(rig.transition.isActive).toBe(true);

    for (let i = 0; i < 30; i += 1) rig.update(FRAME, desired);
    expect(rig.transition.isActive).toBe(false);
    expect(cameraPoseDistance(rig.current, desired)).toBeLessThan(0.01);

    const moved = createCameraPose({ x: -4, y: 3, z: 0 }, { x: -4, y: 0, z: 0 }, 60);
    expect(rig.update(FRAME, moved).position.x).toBeGreaterThan(desired.position.x);
    for (let i = 0; i < 120; i += 1) rig.update(FRAME, moved);
    expect(rig.current.position.x).toBeCloseTo(moved.position.x, 2);
  });

  it('pulls the camera in front of blocking geometry', () => {
    const raycaster: CameraRaycaster = { cast: () => ({ distance: 2 }) };
    const blocked = createCameraPose({ x: 0, y: 0, z: 10 }, { x: 0, y: 0, z: 0 }, 55);
    const rig = new SmoothCameraRig(blocked, { raycaster, collision: { clearance: 0.5 } });
    expect(rig.update(FRAME, blocked).position.z).toBeCloseTo(1.5, 6);
  });
});
